def serialize_select(
    data_list: List[bytes], output_details: Optional[Dict[str, Any]]
) -> bytes:
    record_delimiter = None
    if output_details:
        json_settings = output_details.get("JSON", {})
        if isinstance(json_settings, dict):
            record_delimiter = json_settings.get("RecordDelimiter")
        if record_delimiter is None:
            csv_settings = output_details.get("CSV", {})
            if isinstance(csv_settings, dict):
                record_delimiter = csv_settings.get("RecordDelimiter")
    delimiter = (record_delimiter if record_delimiter is not None else "\n").encode(
        "utf-8"
    )
    response = b""
    for data in data_list:
        response += _create_data_message(data + delimiter)
    return response + _create_stats_message() + _create_end_message()
